import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

/// Project-owned, synthetic one-word speech sample ("three").
///
/// Its raw PCM is embedded as gzip-compressed data and wrapped as WAV only for
/// the request,
/// and contains no recorded performance or copyrighted media.
abstract final class AudioTestData {
  static const sampleRate = 16000;
  static const channelCount = 1;

  static String get wavBase64 => base64Encode(wavBytes());

  static Uint8List wavBytes() {
    // Correct the single damaged character from the generated embedded payload.
    final encoded = _gzipBase64.replaceFirst('+6nzSj7', '+6nzij7');
    final pcm = gzip.decode(base64Decode(encoded));
    final wav = Uint8List(44 + pcm.length);
    final header = ByteData.sublistView(wav, 0, 44);
    wav.setRange(0, 4, 'RIFF'.codeUnits);
    header.setUint32(4, 36 + pcm.length, Endian.little);
    wav.setRange(8, 12, 'WAVE'.codeUnits);
    wav.setRange(12, 16, 'fmt '.codeUnits);
    header.setUint32(16, 16, Endian.little);
    header.setUint16(20, 1, Endian.little);
    header.setUint16(22, channelCount, Endian.little);
    header.setUint32(24, sampleRate, Endian.little);
    header.setUint32(28, sampleRate * channelCount * 2, Endian.little);
    header.setUint16(32, channelCount * 2, Endian.little);
    header.setUint16(34, 16, Endian.little);
    wav.setRange(36, 40, 'data'.codeUnits);
    header.setUint32(40, pcm.length, Endian.little);
    wav.setRange(44, wav.length, pcm);
    return wav;
  }

  static const _gzipBase64 =
      '';
}
